// ─────────────────────────────────────────────────────────────
//  hooks/useFoods.js
//  Reusable hook that manages fetch state for food data
// ─────────────────────────────────────────────────────────────

import { useState, useEffect, useCallback } from 'react';
import { getRecommendations, searchByQuery } from '../services/openFoodFacts';
import { getWeatherContext } from '../services/weather';

export function useWeatherContext() {
  const [weather, setWeather] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const context = await getWeatherContext();
      setWeather(context);
    } catch (e) {
      setError(e.message || 'Weather unavailable.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  return { weather, loading, error, reload: load };
}

// Simple in-memory cache to prevent multiple skeletons and late refreshes
let cachedRecommendations = null;

// ── Hook: personalised recommendations ──────────────────────
export function useRecommendations(preferences, count = 20, weather = null) {
  const [foods,   setFoods]   = useState(cachedRecommendations || []);
  const [loading, setLoading] = useState(!cachedRecommendations);
  const [error,   setError]   = useState(null);

  const load = useCallback(async () => {
    if (!preferences?.dietType) return;

    // Only trigger skeleton loading state if there are no foods loaded/cached yet
    if (foods.length === 0) {
      setLoading(true);
    }
    setError(null);
    try {
      const results = await getRecommendations({ ...preferences, weather }, count);
      setFoods(results);
      cachedRecommendations = results;
    } catch (e) {
      if (foods.length === 0) {
        setError('Failed to load recommendations. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  }, [preferences, count, weather, foods.length]);

  useEffect(() => { load(); }, [load]);

  return { foods, loading, error, reload: load };
}

// ── Hook: search query ───────────────────────────────────────
export function useSearch(query, preferences) {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState(null);

  useEffect(() => {
    if (!query || query.trim().length < 2) {
      setResults([]);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    const timer = setTimeout(async () => {
      try {
        const data = await searchByQuery(query, preferences || {}, 25);
        if (!cancelled) setResults(data);
      } catch {
        if (!cancelled) setError('Search failed. Please try again.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    }, 500); // 500ms debounce

    return () => { cancelled = true; clearTimeout(timer); };
  }, [query, preferences]);

  return { results, loading, error };
}
